        }
        update: {
          x: {scale: "x", field: "stack"}
          y: {field: "scaledY0"}
          y2: {field: "scaledY1"}
          fillOpacity: {value: 0.6}
          tooltip: {
            signal: datum.grpId + '   ' + format(datum.total, ',.0f') + '   (' + format(datum.percentage, '.1%') + ')'
          }
        }
        hover: {
          fillOpacity: {value: 1}
        }
      }
    }
    {
      // draw country code labels on the inner side of the stack
      type: text
      from: {data: "groups"}
      // don't process events for the labels - otherwise line mouseover is unclean
      interactive: false
      encode: {
        update: {
          // depending on which stack it is, position x with some padding
          x: {
            signal: scale('x', datum.stack) + (datum.rightLabel ? bandwidth('x') + 8 : -8)
          }
          // middle of the group
          yc: {signal: "(datum.scaledY0 + datum.scaledY1)/2"}
          align: {signal: "datum.rightLabel ? 'left' : 'right'"}
          baseline: {value: "middle"}
          fontWeight: {value: "bold"}
          // only show text label if the group's height is large enough
          text: {signal: "abs(datum.scaledY0-datum.scaledY1) > 13 ? datum.grpId : ''"}
        }
      }
    }
    {
      // Create a "show all" button. Shown only when a country is selected.
      type: group
      data: [
        // We need to make the button show only when groupSelector signal is true.
        // Each mark is drawn as many times as there are elements in the backing data.
        // Which means that if values list is empty, it will not be drawn.
        // Here I create a data source with one empty object, and filter that list
        // based on the signal value. This can only be done in a group.
        {
          name: dataForShowAll
          values: [{}]
          transform: [{type: "filter", expr: "groupSelector"}]
        }
      ]
      // Set button size and positioning
      encode: {
        enter: {
          xc: {signal: "width/2"}
          y: {value: 30}
          width: {value: 80}
          height: {value: 30}
        }
      }
      marks: [
        {
          // This group is shown as a button with rounded corners.
          type: group
          // mark name allows signal capturing
          name: groupReset
          // Only shows button if dataForShowAll has values.
          from: {data: "dataForShowAll"}
          encode: {
            enter: {
              cornerRadius: {value: 6}
              fill: {value: "#f5f5f5"}
              stroke: {value: "#c1c1c1"}
              strokeWidth: {value: 2}
              // use parent group's size
              height: {
                field: {group: "height"}
              }
              width: {
                field: {group: "width"}
              }
            }
            update: {
              // groups are transparent by default
              opacity: {value: 1}
            }
            hover: {
              opacity: {value: 0.7}
            }
          }
          marks: [
            {
              type: text
              // if true, it will prevent clicking on the button when over text.
              interactive: false
              encode: {
                enter: {
                  // center text in the paren group
                  xc: {
                    field: {group: "width"}
                    mult: 0.5
                  }
                  yc: {
                    field: {group: "height"}
                    mult: 0.5
                    offset: 2
                  }
                  align: {value: "center"}
                  baseline: {value: "middle"}
                  fontWeight: {value: "bold"}
                  text: {value: "Show All"}
                }
              }
            }
          ]
        }
      ]
    }
  ]
  signals: [
    {
      // used to highlight traffic to/from the same country
      name: groupHover
      value: {}
      on: [
        {
          events: @groupMark:mouseover
          update: "{stk1:datum.stack=='stk1' && datum.grpId, stk2:datum.stack=='stk2' && datum.grpId}"
        }
        {events: "mouseout", update: "{}"}
      ]
    }
    // used to filter only the data related to the selected country
    {
      name: groupSelector
      value: false
      on: [
        {
          // Clicking groupMark sets this signal to the filter values
          events: @groupMark:click!
          update: "{stack:datum.stack, stk1:datum.stack=='stk1' && datum.grpId, stk2:datum.stack=='stk2' && datum.grpId}"
        }
        {
          // Clicking "show all" button, or double-clicking anywhere resets it
          events: [
            {type: "click", markname: "groupReset"}
            {type: "dblclick"}
          ]
          update: "false"
        }
      ]
    }
  ]
}"},"title":"[GCP] Sankey Source to Destination subnetwork","type":"vega","uiState":{}},"type":"visualization"},"title":"Sankey Source to Destination autonomous system (AS) org name"},{"version":"8.9.0","type":"lens","gridData":{"h":15,"i":"fcaf1c3c-64a6-47ce-90a2-8226e788c062","w":24,"x":24,"y":56},"panelIndex":"fcaf1c3c-64a6-47ce-90a2-8226e788c062","embeddableConfig":{"attributes":{"references":[{"id":"logs-*","name":"indexpattern-datasource-layer-8929ffe2-4cf7-40b7-8e2c-1ee52bdd8d97","type":"index-pattern"},{"id":"logs-*","name":"abef953e-0b21-4e7f-b488-92850705970c","type":"index-pattern"}],"state":{"adHocDataViews":{},"datasourceStates":{"formBased":{"layers":{"8929ffe2-4cf7-40b7-8e2c-1ee52bdd8d97":{"columnOrder":["06178db9-8ae7-4706-b479-29aea6be4d75","313bb272-53cc-4d90-890e-d0952e9fd07f","bbc2b648-d5e5-4ee1-baed-be4d1497e963"],"columns":{"06178db9-8ae7-4706-b479-29aea6be4d75":{"customLabel":true,"dataType":"string","isBucketed":true,"label":"Source AS Org","operationType":"terms","params":{"missingBucket":true,"orderBy":{"columnId":"bbc2b648-d5e5-4ee1-baed-be4d1497e963","type":"column"},"orderDirection":"desc","otherBucket":true,"size":10},"scale":"ordinal","sourceField":"source.as.organization.name"},"313bb272-53cc-4d90-890e-d0952e9fd07f":{"customLabel":true,"dataType":"string","isBucketed":true,"label":"Destination AS Org","operationType":"terms","params":{"missingBucket":true,"orderBy":{"columnId":"bbc2b648-d5e5-4ee1-baed-be4d1497e963","type":"column"},"orderDirection":"desc","otherBucket":true,"size":10},"scale":"ordinal","sourceField":"destination.as.organization.name"},"bbc2b648-d5e5-4ee1-baed-be4d1497e963":{"customLabel":true,"dataType":"number","isBucketed":false,"label":"Total bytes","operationType":"sum","params":{"format":{"id":"bytes","params":{"decimals":2}}},"scale":"ratio","sourceField":"network.bytes"}},"incompleteColumns":{}}}}},"filters":[{"$state":{"store":"appState"},"meta":{"alias":null,"disabled":false,"field":"data_stream.dataset","ind